export const code = async (inputs) => {
  const leadsRouted = Number(inputs.leadsRouted) || 0;
  const atRiskValue = Number(inputs.atRiskValue) || 0;
  const atRiskCount = Number(inputs.atRiskCount) || 0;
  const healthScore = Number(inputs.healthScore) || 0;

  // Illustrative, transparent methodology (documented in README, adjustable per client):
  // - Assume $500 of protected pipeline value per lead routed in under 60s vs a slow manual process
  // - Assume flagging an at-risk deal before the deal review recovers ~20% of its value on average
  const fastRoutingValue = leadsRouted * 500;
  const dealRescueValue = Math.round(atRiskValue * 0.20);
  const leakagePrevented = fastRoutingValue + dealRescueValue;

  return {
    leadsRouted,
    atRiskCount,
    atRiskValue,
    healthScore,
    fastRoutingValue,
    dealRescueValue,
    leakagePrevented
  };
};

